export interface CoachChatMessage {
  /** "staff" is a care-team message the patient saw in this thread. The server replays it to the model as context only; the coach never answers it or speaks for the care team. */
  role: CoachChatMessageRole;
  /** @maxLength 4000 */
  content: string;
  /** True when the patient stopped this assistant reply mid-stream, so its text is an incomplete fragment. The server annotates flagged replies before replaying them to the model, keeping the next answer from continuing the cut-off sentence. Ignored on user messages. */
  stopped?: boolean;
  /**
     * Optional photo attached to this user message, as a base64 data URI (JPEG, PNG, or WebP). Honored only on the final message of the request — history replays carry text only, so a photo is never re-sent on later turns. Analyzed in memory and never stored. Ignored on assistant messages.
     * @maxLength 8000000
     */
  image?: string;
  /** What the attached photo shows, chosen by the client flow that captured it: "menu" runs the restaurant menu scan; "meal" runs the meal analysis that identifies visible foods with estimated portions and returns an editable meal card; "label" runs the nutrition label reader that transcribes the printed facts and emits a labelDraft event for the client's name conversation. When absent, the server inspects the photo and routes it to the fitting pipeline itself. Ignored without an image. */
  photoKind?: CoachChatMessagePhotoKind;
}

/**
 * Explicit diary slot for any card generated on this turn, sent by entry points that already know which meal is being logged (for example a per-meal camera on a diary row). Wins over both a meal the patient names and the time-of-day default, and flows through to the card payload untouched.
 */
export type CoachChatInputMealSlot = typeof CoachChatInputMealSlot[keyof typeof CoachChatInputMealSlot];


export const CoachChatInputMealSlot = {
  breakfast: 'breakfast',
  lunch: 'lunch',
  dinner: 'dinner',
  snacks: 'snacks',
} as const;

export interface CoachChatInput {
  /**
     * @minItems 1
     * @maxItems 30
     */
  messages: CoachChatMessage[];
  /**
     * The patient's device-local wall clock when this turn was sent, as 24-hour "HH:MM" (for example "14:05"). Used only to preselect the diary slot on a recipe or meal card generated this turn when the patient names no meal: the server derives a time-of-day default (around 2 pm that is lunch) for the prompts and the missing-slot fallbacks. Unparseable values are ignored, and when the field is absent (older clients) the server keeps its legacy defaults.
     * @maxLength 5
     */
  localTime?: string;
  /** Explicit diary slot for any card generated on this turn, sent by entry points that already know which meal is being logged (for example a per-meal camera on a diary row). Wins over both a meal the patient names and the time-of-day default, and flows through to the card payload untouched. */
  mealSlot?: CoachChatInputMealSlot;
  /**
     * The app's own calendar date for this turn as "YYYY-MM-DD". Sent only with authenticated (signed-in patient) requests so the server grounds the coach's live "today so far" context on the same diary day the app is showing. Absent for the demo persona and older clients; invalid values are ignored server-side.
     * @maxLength 10
     * @pattern ^\d{4}-\d{2}-\d{2}$
     */
  localDate?: string;
}

